 "Ninatengenezaje ankara ya mauzo?": {
  "sw": "Ninatengenezaje ankara ya mauzo?",
  "en": "How do I create a sales invoice?"
 },
 "Nenda Sales > Ankara Mpya, chagua mteja, ongeza bidhaa (unaweza kuscan barcode), weka malipo kisha Hifadhi Ankara. Stoo inapungua kiotomatiki.": {
  "sw": "Nenda Sales > Ankara Mpya, chagua mteja, ongeza bidhaa (unaweza kuscan barcode), weka malipo kisha Hifadhi Ankara. Stoo inapungua kiotomatiki.",
  "en": "Go to Sales > New Invoice, choose a customer, add products (you can scan a barcode), enter the payment, then Save Invoice. Stock decreases automatically."
 },
 "Ninaingizaje bidhaa nyingi kwa Excel?": {
  "sw": "Ninaingizaje bidhaa nyingi kwa Excel?",
  "en": "How do I import many products with Excel?"
 },
 "Nenda Stock > Import from Excel, pakua template, jaza jina, bei ya kuuzia, bei ya manunuzi na idadi, kisha pakia faili. Hakiki na ubonyeze Ingiza.": {
  "sw": "Nenda Stock > Import from Excel, pakua template, jaza jina, bei ya kuuzia, bei ya manunuzi na idadi, kisha pakia faili. Hakiki na ubonyeze Ingiza.",
  "en": "Go to Stock > Import from Excel, download the template, fill in the name, selling price, buying price and quantity, then upload the file. Review and press Import."
 },
 "Ninarekodije mtaji wa kuanzisha biashara?": {
  "sw": "Ninarekodije mtaji wa kuanzisha biashara?",
  "en": "How do I record the capital that starts the business?"
 },
 "Nenda Accounts > Mapokezi ya Mtaji, chagua mtaji umetoka wapi (mmiliki, mkurugenzi, mkopo wa benki...) na fedha ziliingia wapi. Hesabu zinasasishwa kiotomatiki.": {
  "sw": "Nenda Accounts > Mapokezi ya Mtaji, chagua mtaji umetoka wapi (mmiliki, mkurugenzi, mkopo wa benki...) na fedha ziliingia wapi. Hesabu zinasasishwa kiotomatiki.",
  "en": "Go to Accounts > Capital Receipts, choose where the capital came from (owner, director, bank loan...) and where the money went. The accounts update automatically."
 },
 "Ninalipaje bili za pango, umeme au maji?": {
  "sw": "Ninalipaje bili za pango, umeme au maji?",
  "en": "How do I pay rent, electricity or water bills?"
 },
 "Nenda Bills, bonyeza Bili mpya, kisha Lipa utakapolipa. Unaweza kulipa kwa awamu; bili zilizochelewa zinakuja kwenye Notifications.": {
  "sw": "Nenda Bills, bonyeza Bili mpya, kisha Lipa utakapolipa. Unaweza kulipa kwa awamu; bili zilizochelewa zinakuja kwenye Notifications.",
  "en": "Go to Bills, press New bill, then Pay when you pay it. You can pay in instalments; overdue bills appear in Notifications."
 },
 "Ninasajili vipi alama ya kidole au Face ID kwa mfanyakazi?": {
  "sw": "Ninasajili vipi alama ya kidole au Face ID kwa mfanyakazi?",
  "en": "How do I register a fingerprint or Face ID for an employee?"
 },
 "Nenda HR > Employees, bonyeza ikoni ya kidole kwenye safu ya mfanyakazi na ufuate maelekezo ya kifaa. Tumia kifaa chenye kisoma kidole, Face ID au Windows Hello, kwenye HTTPS.": {
  "sw": "Nenda HR > Employees, bonyeza ikoni ya kidole kwenye safu ya mfanyakazi na ufuate maelekezo ya kifaa. Tumia kifaa chenye kisoma kidole, Face ID au Windows Hello, kwenye HTTPS.",
  "en": "Go to HR > Employees, press the fingerprint icon on the employee's row and follow the device prompts. Use a device with a fingerprint reader, Face ID or Windows Hello, over HTTPS."
 },
 "Mfanyakazi anaingiaje kazini kwa alama ya kidole?": {
  "sw": "Mfanyakazi anaingiaje kazini kwa alama ya kidole?",
  "en": "How does an employee sign in with a fingerprint?"
 },
 "Nenda Payroll > Staff Sign In, bonyeza Ingia kazini, kisha thibitisha kwa alama ya kidole au uso. Kutoka kazini tumia Staff Sign Out.": {
  "sw": "Nenda Payroll > Staff Sign In, bonyeza Ingia kazini, kisha thibitisha kwa alama ya kidole au uso. Kutoka kazini tumia Staff Sign Out.",
  "en": "Go to Payroll > Staff Sign In, press Sign in to work, then verify with your fingerprint or face. To leave, use Staff Sign Out."
 },
 "Ninahesabuje na kulipaje mishahara?": {
  "sw": "Ninahesabuje na kulipaje mishahara?",
  "en": "How do I calculate and pay payroll?"
 },
 "Nenda Payroll > Process Payroll, weka kipindi, bonyeza Hesabu. Mahudhurio na likizo bila malipo huzingatiwa. Idhinisha kisha Lipa; journal inatengenezwa kiotomatiki.": {
  "sw": "Nenda Payroll > Process Payroll, weka kipindi, bonyeza Hesabu. Mahudhurio na likizo bila malipo huzingatiwa. Idhinisha kisha Lipa; journal inatengenezwa kiotomatiki.",
  "en": "Go to Payroll > Process Payroll, set the period and press Calculate. Attendance and unpaid leave are taken into account. Approve then Pay; the journal is created automatically."
 },
 "Ninabadilishaje lugha ya mfumo?": {
  "sw": "Ninabadilishaje lugha ya mfumo?",
  "en": "How do I change the system language?"
 },
 "Nenda Maintenance > Language Settings, chagua Kiswahili au English na uhifadhi. Mfumo mzima utatumia lugha moja.": {
  "sw": "Nenda Maintenance > Language Settings, chagua Kiswahili au English na uhifadhi. Mfumo mzima utatumia lugha moja.",
  "en": "Go to Maintenance > Language Settings, choose Kiswahili or English and save. The whole system will use one language."
 },
 "Ninabadilishaje biashara?": {
  "sw": "Ninabadilishaje biashara?",
  "en": "How do I switch business?"
 },
 "Super Admin anabonyeza Badilisha biashara juu ya skrini kurudi kwenye orodha ya biashara, kisha achague nyingine.": {
  "sw": "Super Admin anabonyeza Badilisha biashara juu ya skrini kurudi kwenye orodha ya biashara, kisha achague nyingine.",
  "en": "The Super Admin presses Switch business at the top of the screen to return to the list of businesses, then picks another one."
 },
 "Ninaunganishaje printer ya risiti?": {
  "sw": "Ninaunganishaje printer ya risiti?",
  "en": "How do I connect a receipt printer?"
 },
 "Nenda Maintenance > Hardware Setup, chagua aina ya muunganisho (waya au wireless), tafuta printer kisha bonyeza Jaribu kuchapa.": {
  "sw": "Nenda Maintenance > Hardware Setup, chagua aina ya muunganisho (waya au wireless), tafuta printer kisha bonyeza Jaribu kuchapa.",
  "en": "Go to Maintenance > Hardware Setup, choose the connection type (wired or wireless), search for the printer, then press Test print."
 },
 "Bidhaa ikiisha ninajuaje?": {
  "sw": "Bidhaa ikiisha ninajuaje?",
  "en": "How do I know when a product runs out?"
 },
 "Mfumo unakutumia taarifa kwenye Notifications bidhaa ikifika kiwango cha kuagiza upya au ikiisha. Weka Reorder Level kwenye kila bidhaa.": {
  "sw": "Mfumo unakutumia taarifa kwenye Notifications bidhaa ikifika kiwango cha kuagiza upya au ikiisha. Weka Reorder Level kwenye kila bidhaa.",
  "en": "The system sends a notice in Notifications when a product reaches its reorder level or runs out. Set a Reorder Level on every product."
 },
 "Nakala rudufu (backup) ninapataje?": {
  "sw": "Nakala rudufu (backup) ninapataje?",
  "en": "Where do I get a backup?"
 },
 "Super Admin: Maintenance > Backup and Restore > Download backup now. Hifadhi faili mahali salama mara kwa mara.": {
  "sw": "Super Admin: Maintenance > Backup and Restore > Download backup now. Hifadhi faili mahali salama mara kwa mara.",
  "en": "Super Admin: Maintenance > Backup and Restore > Download backup now. Keep the file somewhere safe, regularly."
 },
